// === OFFLINE SHARE LINK GENERATOR (COMPRESSION & BASE64) ===
function compactPayload(data) {
    const SECTION_MAP = {
        "1. Котёл + водонагреватель": 1,
        "2. Обвязка котельной": 2,
        "3. Радиаторное отопление": 3,
        "4. Водяной теплый пол": 4,
        "5. Горячее водоснабжение": 5,
        "6. Водопровод и канализация": 6,
        "7. Управление отоплением": 7,
        "8. Монтажные элементы": 8,
        "9. Дополнительные материалы": 9,
        "10. Ввод ХВС и водоочистка": 10,
        "11. Скважина / Колодец": 11
    };

    return {
        o: {
            n: data.object_info.projectName || "Новый объект",
            a: data.object_info.area || 0,
            f: data.object_info.floors || 1,
            r: data.object_info.res || 1,
            m: data.object_info.mat || 1,
            p: data.object_info.power || 0,
            g: data.object_info.region || 'Центр',
            d: data.object_info.date || '',
            s: data.object_info.showSku ? 1 : 0,
            c: data.object_info.eqDiscount || 0,
            q: data.object_info.sequence_id || '',
            // Прайс-лист дистрибьютора. У обычных позиций в ссылку уходит только
            // артикул, а цену invoice.html берёт из каталога сам — без этого ключа
            // клиент увидел бы цены Терема, а итог в шапке был бы посчитан по ценам
            // дистрибьютора, и строки со сметой не сошлись бы.
            k: data.object_info.priceListKey || ''
        },
        m: {
            n: data.manager_info.name || '',
            p: data.manager_info.phone || '',
            c: data.manager_info.city || '',
            e: data.manager_info.email || ''
        },
        i: {
            e: (data.items.equipment || []).map(item => {
                const isCustom = item.id && String(item.id).startsWith('custom_');
                if (isCustom) {
                    return {
                        id: item.id,
                        n: item.name || '',
                        b: item.brand || '',
                        u: item.unit || '',
                        p: item.price || 0,
                        q: item.q || 0,
                        t: SECTION_MAP[item.sectionTitle] || item.sectionTitle || 9,
                        c: 1
                    };
                } else {
                    return {
                        s: item.displaySku || item.sku || item.id || '',
                        q: item.q || 0,
                        t: SECTION_MAP[item.sectionTitle] || item.sectionTitle || 9,
                        o: item.isOpt ? 1 : 0,
                        d: item.desc || ''
                    };
                }
            }),
            w: (data.items.works || []).map(item => ({
                n: item.name || '',
                q: item.q || item.qty || 0,
                p: item.price || 0
            }))
        },
        t: {
            e: data.totals.equipment || 0,
            w: data.totals.works || 0,
            g: data.totals.grandTotal || 0
        }
    };
}

function base64Encode(str) {
    return btoa(encodeURIComponent(str).replace(/%([0-9A-F]{2})/g, function (match, p1) {
        return String.fromCharCode(parseInt(p1, 16));
    }));
}

async function compressString(str) {
    const byteArray = new TextEncoder().encode(str);
    const cs = new CompressionStream('deflate');
    const writer = cs.writable.getWriter();
    writer.write(byteArray);
    writer.close();
    const response = new Response(cs.readable);
    const arrayBuffer = await response.arrayBuffer();

    let binary = '';
    const bytes = new Uint8Array(arrayBuffer);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

async function encodePayload(data) {
    const json = JSON.stringify(compactPayload(data));
    try {
        if (typeof CompressionStream !== 'undefined') {
            const compressed = await compressString(json);
            return 'c_' + encodeURIComponent(compressed);
        }
    } catch (e) {
        console.warn('CompressionStream failed, using raw base64:', e);
    }
    return 'r_' + encodeURIComponent(base64Encode(json));
}
