document.addEventListener('DOMContentLoaded', function () { app.init(); });

// Автоматическая генерация мульти-страничного документа перед печатью. Вынесена в отдельную
// именованную функцию (а не анонимный обработчик), чтобы её можно было вызвать напрямую из
// executeDownload() на мобильных/планшетах — там PDF скачивается через html2pdf() без
// настоящего window.print(), поэтому событие 'beforeprint' само по себе не сработает.
function prepareForPrint() {
    document.body.classList.remove('dark-mode');

    // 1. Создаем или очищаем скрытый контейнер, который увидит только принтер
    let printBin = document.getElementById('print_bin');
    if (!printBin) {
        printBin = document.createElement('div');
        printBin.id = 'print_bin';
        document.body.appendChild(printBin);
    }
    printBin.innerHTML = '';

    // Retrieve selected options from app.printOptions (default to true if undefined)
    const showEq = app.printOptions ? app.printOptions.eq : true;
    const showWorks = app.printOptions ? app.printOptions.works : true;
    const showHeatLossOpt = app.printOptions ? app.printOptions.heatLoss : true;
    const showSchemeOpt = app.printOptions ? app.printOptions.scheme : true;

    // Запоминаем текущее состояние
    let originalMode = app.state.viewMode;
    let printArea = document.getElementById('print-area');

    if (printArea) {
        // --- ШАГ 1: ЛИСТ ОБОРУДОВАНИЯ ---
        if (showEq) {
            app.state.viewMode = 'equipment';
            app.render();
            let eqClone = printArea.cloneNode(true);
            eqClone.id = 'print_eq_clone';
            // Убираем схему и табы
            let eqScheme = eqClone.querySelector('#dynamic_scheme');
            if (eqScheme) eqScheme.remove();
            let eqTabs = eqClone.querySelector('.main-view-tabs');
            if (eqTabs) eqTabs.style.display = 'none';
            printBin.appendChild(eqClone);
        }

        // --- ШАГ 2: ЛИСТ МОНТАЖНЫХ РАБОТ (Доступно авторизованным пользователям на любом
        // тарифе — Базовый и Профи, только гость не имеет доступа к разделу работ) ---
        let isGuest = !app.state.tgUser;

        if (showWorks && !isGuest) {
            app.state.viewMode = 'works';
            app.render();
            let worksClone = printArea.cloneNode(true);
            worksClone.id = 'print_works_clone';
            if (showEq) {
                worksClone.classList.add('print-page-break'); // Разрыв страницы
            }
            let worksScheme = worksClone.querySelector('#dynamic_scheme');
            if (worksScheme) worksScheme.remove();
            let wTabs = worksClone.querySelector('.main-view-tabs');
            if (wTabs) wTabs.style.display = 'none';

            // === ВЫРЕЗАЕМ ЛИШНИЕ КОЛОНКИ ДЛЯ ЭКОНОМИИ МЕСТА ===
            worksClone.querySelectorAll('table').forEach(table => {
                let headers = table.querySelectorAll('thead th');
                let hideIdx = [];
                // Ищем индексы ненужных колонок
                headers.forEach((th, idx) => {
                    let txt = th.innerText.trim().toUpperCase();
                    if (txt === 'БРЕНД' || txt === 'АРТИКУЛ' || txt === 'ФОТО') {
                        hideIdx.push(idx);
                    }
                });
                // Скрываем эти ячейки во всех строках
                if (hideIdx.length > 0) {
                    table.querySelectorAll('tr').forEach(row => {
                        let cells = row.children;
                        hideIdx.forEach(idx => {
                            if (cells[idx]) cells[idx].style.display = 'none';
                        });
                    });
                }
            });
            // ==================================================

            printBin.appendChild(worksClone);
        }

        // --- ШАГ 3: СХЕМА (На отдельном листе, независимо от раздела ОБОРУДОВАНИЕ/РАБОТЫ —
        // управляется отдельным чекбоксом в окне печати) ---
        if (showSchemeOpt && app.state.showScheme) {
            app.state.viewMode = 'equipment'; // Схема генерится только на этой вкладке
            app.render();
            let currentScheme = document.getElementById('dynamic_scheme');
            if (currentScheme) {
                let schemeClone = currentScheme.cloneNode(true);
                // Разрыв страницы нужен, только если перед схемой уже что-то напечатано
                // (иначе, если схема — первый выбранный раздел, получаем пустую первую страницу).
                if (printBin.children.length > 0) {
                    schemeClone.classList.add('print-page-break');
                }
                printBin.appendChild(schemeClone);
            }
        }

        // --- ШАГ 4: ТАБЛИЦА ТЕПЛОПОТЕРЬ (Подробный режим + готовый расчёт по комнатам,
        // управляется отдельным чекбоксом в окне печати) ---
        if (showHeatLossOpt && app.state.detailedRooms && app.state.showDetailedRoomsPanel) {
            let heatLossHtml = app.renderHeatLossTable();
            if (heatLossHtml) {
                let hlContainer = document.createElement('div');
                hlContainer.id = 'heat_loss_table_page';
                hlContainer.innerHTML = heatLossHtml;
                // Разрыв страницы нужен, только если перед таблицей уже что-то напечатано
                // (иначе, если теплопотери — единственный выбранный раздел, получаем пустую
                // первую страницу перед таблицей).
                if (printBin.children.length > 0) {
                    hlContainer.classList.add('print-page-break');
                }
                printBin.appendChild(hlContainer);
            }
        }

        // --- #16: ПРЕДУПРЕЖДЕНИЯ О НЕХВАТКЕ МОЩНОСТИ ---
        // Это технические замечания для монтажника (дефицит приборов по помещениям). В смету
        // для клиента они не идут никогда — на экране расчёта видны, на печати/в PDF скрыты.
        // Класс снимается в cleanupAfterPrint.
        document.body.classList.add('hide-warns-print');

        // --- ШАГ 5: ПРЯЧЕМ ОРИГИНАЛ ОТ ПРИНТЕРА ---
        printArea.classList.add('hide-original-for-print');
        let liveScheme = document.getElementById('dynamic_scheme');
        if (liveScheme) liveScheme.classList.add('hide-original-for-print');

        // Возвращаем интерфейс в исходное состояние
        app.state.viewMode = originalMode;
        app.render();
    }
}
window.addEventListener('beforeprint', prepareForPrint);

// Возврат к нормальной жизни после закрытия окна печати. Так же вынесена в именованную
// функцию — вызывается напрямую из executeDownload() после html2pdf() на мобильных/планшетах,
// где событие 'afterprint' не наступает (не было настоящего window.print()).
function cleanupAfterPrint() {
    if (app && app.state && app.state.darkMode) {
        document.body.classList.add('dark-mode');
    }

    // Возвращаем видимость оригинальному интерфейсу
    let printArea = document.getElementById('print-area');
    let liveScheme = document.getElementById('dynamic_scheme');
    if (printArea) printArea.classList.remove('hide-original-for-print');
    if (liveScheme) liveScheme.classList.remove('hide-original-for-print');
    // #16: возвращаем предупреждения о нехватке мощности в интерфейс после печати
    document.body.classList.remove('hide-warns-print');

    // Очищаем корзину печати
    let printBin = document.getElementById('print_bin');
    if (printBin) printBin.innerHTML = '';
}
window.addEventListener('afterprint', cleanupAfterPrint);

// Датчик прокрутки для сужения шапки
window.addEventListener('scroll', function () {
    let header = document.querySelector('.site-header');
    if (header) {
        // Если прокрутили больше чем на 40 пикселей - включаем режим "узкой шапки"
        if (window.scrollY > 40) {
            header.classList.add('scrolled');
        } else {
            header.classList.remove('scrolled');
        }
    }
});